package com.gomgomapps.math.core;
import org.junit.Test;
import static org.junit.Assert.*;
import java.io.*;
import java.time.LocalDate;
import java.util.*;
public class KoreanFoundationAscendingTest {
 private static final LocalDate DAY=LocalDate.of(2026,10,15);
 private Learning.State student(boolean screen){Learning.State s=new Learning.State();s.profile.grade=6;s.profile.term=2;s.profile.schoolYear=2026;s.profile.curriculum=2022;s.profile.ready=true;s.profile.foundationAscending=screen;return s;}
 private Learning.State copy(Learning.State s)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ObjectOutputStream out=new ObjectOutputStream(bytes)){out.writeObject(s);}try(ObjectInputStream in=new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))){return (Learning.State)in.readObject();}}
 private KoreanFoundationUnits.Unit unit(Learning.Profile p,int g,int t,int u){return KoreanFoundationUnits.available(p).stream().filter(x->x.grade()==g&&x.term()==t&&x.unit()==u).findFirst().orElseThrow();}
 @Test public void ExplicitUnitsSeparateConceptsAndVersionSpecificEndpointsIncludeTheWholeLearnedUnit(){
  Learning.Profile p=student(true).profile;KoreanFoundationUnits.Unit arithmetic=unit(p,1,1,3);assertEquals(List.of("add9","sub9"),arithmetic.representatives());assertTrue(arithmetic.members().containsAll(List.of("join9","split9")));
  p.lastLearnedSkill=arithmetic.endpointSkill();assertTrue(KoreanFoundationUnits.scope(p).containsAll(arithmetic.members()));assertFalse(KoreanFoundationUnits.scope(p).contains("place50"));
  assertEquals(List.of("el_circle_circumference","el_circle_area"),unit(p,6,2,5).representatives());assertFalse(unit(p,6,2,5).members().contains("el_circle_graph"));assertTrue(unit(p,6,1,5).members().contains("el_circle_graph"));assertTrue(unit(p,6,1,6).members().contains("el_rect_prism_volume"));assertTrue(unit(p,6,2,6).representatives().isEmpty());
  assertTrue(unit(p,6,2,3).members().contains("decimalDiv"));p.curriculum=2015;assertTrue(unit(p,6,2,2).members().contains("decimalDiv"));assertTrue(unit(p,6,2,3).representatives().isEmpty());
  p.curriculum=2022;p.lastLearnedSkill="";assertFalse(KoreanFoundationUnits.learned(p).stream().anyMatch(x->x.grade()==6&&x.term()==2));
 }
 @Test public void RevisedPublisherUnitsDoNotIncludeLaterDecimalsOrExcludeAlreadyStudiedFractions(){
  Learning.State s=student(true);s.profile.lastLearnedSkill=unit(s.profile,4,1,5).endpointSkill();
  Set<String> scope=new HashSet<>(KoreanFoundationUnits.scope(s.profile));assertTrue(scope.containsAll(List.of("fracAddLike","fracSubLike")));assertFalse(scope.contains("el_bar_graph"));assertFalse(scope.contains("decimalAdd"));
  assertEquals(List.of("decimalAdd","decimalSub"),unit(s.profile,4,2,1).representatives());assertEquals(List.of("krNumberRule","krFigureRule","krCalculationRule","krEqualRelation","krEqualFill"),unit(s.profile,4,2,3).representatives());
  assertTrue(unit(s.profile,3,2,2).members().contains("el_circle_diameter"));assertTrue(unit(s.profile,3,2,3).members().contains("remainder"));assertTrue(unit(s.profile,3,2,4).members().contains("el_mass_add_sub"));assertTrue(unit(s.profile,3,2,5).members().contains("fracCompare"));
  assertTrue(unit(s.profile,1,2,3).members().contains("earlyClock"));assertFalse(unit(s.profile,1,2,5).members().contains("earlyClock"));assertTrue(unit(s.profile,1,2,4).members().contains("add20"));assertFalse(unit(s.profile,2,1,2).members().contains("el_even_odd"));assertTrue(unit(s.profile,2,1,2).members().contains("el_shape_classify"));
  s.profile.lastLearnedSkill=unit(s.profile,3,2,1).endpointSkill();Learning.beginDiagnostic(s,new Random(3706));assertEquals(Integer.valueOf(3),Diagnosis.currentPlan(s).placements.get("mul22"));assertEquals(Integer.valueOf(0),Diagnosis.currentPlan(s).placements.get("count"));
  s.profile.curriculum=2015;assertTrue(unit(s.profile,4,2,1).members().contains("fracAddLike"));
 }
 @Test public void ShortScreenRoundsRemainAscendingAndCountOnlyExplicitCoreChecksWithoutWholeUnitMastery(){
  Learning.State s=student(true);s.profile.lastLearnedSkill=unit(s.profile,1,1,3).endpointSkill();Random r=new Random(370);Learning.beginDiagnostic(s,r);Diagnosis.Plan plan=Diagnosis.currentPlan(s);assertTrue(plan.unitScreening);assertEquals(6,plan.actualGrade);assertEquals(4,Diagnosis.displayedTarget(s.session));
  int expected=KoreanFoundationUnits.learned(s.profile).stream().mapToInt(x->x.representatives().size()).sum(),completed=0,last=-1;Set<String> probes=new HashSet<>();
  while(true){while(!s.session.finished){Question q=Learning.ensureQuestion(s,new Generator(r),DAY);assertNotNull(q);Diagnosis.Probe current=s.session.diagnosticRun.current;Diagnosis.UnitScreen screen=plan.unitScreens.get(current.unitKey);int order=screen.reviewGrade*100+screen.term*10+screen.unit;assertTrue(order>=last);last=order;assertTrue(probes.add(current.unitKey+"|"+q.skillId));Learning.finishQuestion(s,false,DAY,r);completed++;}assertTrue(s.session.completed<=4);if(!Diagnosis.hasRemainingChecks(plan))break;Learning.continueDiagnostic(s,r);}
  assertEquals(expected,completed);assertEquals(6,s.profile.grade);assertEquals(0,Diagnosis.remainingUnits(plan));assertTrue(Diagnosis.screens(plan).stream().filter(x->!x.representatives.isEmpty()).allMatch(x->x.status==Diagnosis.UnitStatus.INDEPENDENT));assertFalse(s.progress.containsKey("join9"));assertFalse(s.progress.containsKey("split9"));
 }
 @Test public void FullSelectedPrimaryEndpointIssuesOnlyItsSupportedCoresInUnitOrder(){
  Learning.State s=student(true);s.profile.lastLearnedSkill=unit(s.profile,6,2,6).endpointSkill();Random r=new Random(3707);Learning.beginDiagnostic(s,r);Diagnosis.Plan plan=Diagnosis.currentPlan(s);
  int expected=KoreanFoundationUnits.learned(s.profile).stream().mapToInt(x->x.representatives().size()).sum(),count=0,last=0;Set<String> seen=new HashSet<>();
  while(true){while(!s.session.finished){Question q=Learning.ensureQuestion(s,new Generator(r),DAY);Diagnosis.Probe probe=s.session.diagnosticRun.current;Diagnosis.UnitScreen u=plan.unitScreens.get(probe.unitKey);int order=u.reviewGrade*100+u.term*10+u.unit;assertTrue(order>=last);last=order;assertTrue(seen.add(u.key+"|"+q.skillId));assertTrue(u.representatives.contains(q.skillId));assertEquals(Set.of("count","compare").contains(q.skillId)?0:u.reviewGrade,probe.reviewGrade);Learning.finishQuestion(s,false,DAY,r);count++;assertTrue(count<=expected);}if(!Diagnosis.hasRemainingChecks(plan))break;Learning.continueDiagnostic(s,r);}
  assertEquals(expected,count);assertEquals(6,s.profile.grade);assertEquals(0,Diagnosis.remainingChecks(plan));assertTrue(Diagnosis.screens(plan).stream().filter(x->x.representatives.isEmpty()).allMatch(x->x.status==Diagnosis.UnitStatus.UNCHECKED));
 }
 @Test public void WrongUnableAndHelpFlagActualUnitsAndContinueWithoutFakeErrorsOrDeferredReplay(){
  Learning.State s=student(true);s.profile.lastLearnedSkill=unit(s.profile,1,1,3).endpointSkill();Random r=new Random(371);Learning.beginDiagnostic(s,r);Diagnosis.Plan plan=Diagnosis.currentPlan(s);Question first=Learning.ensureQuestion(s,new Generator(r),DAY);Diagnosis.UnitScreen screen=plan.unitScreens.get(s.session.diagnosticRun.current.unitKey);Learning.finishQuestion(s,true,DAY,r);assertEquals("unable",screen.reasons.get(first.skillId));assertEquals(Diagnosis.UnitStatus.NEEDS_STUDY,screen.status);assertTrue(s.session.deferred.isEmpty());assertFalse(s.progress(first.skillId).weak());assertEquals(0,plan.checks.values().stream().mapToInt(x->x.errors).sum());assertTrue(Review.track(s.progress(first.skillId)).pending);
  Question second=Learning.ensureQuestion(s,new Generator(r),DAY);Learning.markError(s,DAY);Learning.finishQuestion(s,true,DAY,r);assertFalse(s.progress(second.skillId).weak());assertEquals(1,plan.checks.values().stream().mapToInt(x->x.errors).sum());assertEquals("wrong",plan.unitScreens.values().stream().filter(x->x.reasons.containsKey(second.skillId)).findFirst().orElseThrow().reasons.get(second.skillId));
  Question third=Learning.ensureQuestion(s,new Generator(r),DAY);Review.helpUsed(s,DAY);Learning.finishQuestion(s,false,DAY,r);assertEquals(1,s.progress(third.skillId).assisted);assertTrue(Diagnosis.studyUnits(s).contains(screen));assertTrue(Diagnosis.studySkills(plan).contains(first.skillId));assertFalse(s.session.finished);assertEquals(6,s.profile.grade);
 }
 @Test public void ExclusionsKeepTheSettingsUnitVisibleButNeverSubstituteAnUnrelatedRepresentative(){
  Learning.Profile p=student(true).profile;KoreanFoundationUnits.Unit u=unit(p,1,1,3);p.lastLearnedSkill=u.endpointSkill();p.excluded.add("add9");assertEquals(List.of("sub9"),KoreanFoundationUnits.learned(p).stream().filter(x->x.key().equals(u.key())).findFirst().orElseThrow().representatives());p.excluded.add("sub9");assertTrue(KoreanFoundationUnits.missingRepresentatives(p).stream().anyMatch(x->x.key().equals(u.key())));p.excluded.addAll(u.members());assertTrue(KoreanFoundationUnits.available(p).stream().anyMatch(x->x.key().equals(u.key())));assertFalse(KoreanFoundationUnits.learned(p).stream().anyMatch(x->x.key().equals(u.key())));
  p.lastLearnedSkill=unit(p,6,2,6).endpointSkill();assertTrue(KoreanFoundationUnits.missingRepresentatives(p).stream().anyMatch(x->x.grade()==6&&x.term()==2&&x.unit()==6));
 }
 @Test public void OldFalseForeignKeysAndFrozenSavedPlansKeepTheirOriginalMeaning()throws Exception{
  Learning.State s=student(false);List<String> ids=new ArrayList<>();for(Catalog.Skill skill:Learning.diagnosticScope(s.profile))ids.add(skill.id);Collections.sort(ids);String key=Curriculum.MAPPING_VERSION+"|2026|2022|6|2||"+String.join(",",ids);assertEquals(key,Diagnosis.scopeKey(s.profile));Random r=new Random(372);Learning.beginDiagnostic(s,r);Learning.Session old=s.session;Question q=Learning.ensureQuestion(s,new Generator(r),DAY);old.answers.set(0,"123");assertFalse(old.diagnosticRun.plan.unitScreening);s.profile.foundationAscending=true;s.profile.lastLearnedSkill=unit(s.profile,1,1,3).endpointSkill();Learning.beginDiagnostic(s,r);assertTrue(s.session.diagnosticRun.plan.unitScreening);assertSame(old,s.savedSessions.get(old.id));assertFalse(old.diagnosticRun.plan.foundationAscending);assertNotEquals(key,Diagnosis.scopeKey(s.profile));Learning.State cold=copy(s);assertTrue(cold.session.diagnosticRun.plan.unitScreening);Learning.resume(cold,old.id);assertEquals(q.id,Learning.ensureQuestion(cold,new Generator(r),DAY).id);assertEquals("123",cold.session.answers.get(0));
  Learning.Profile foreign=new Learning.Profile();foreign.countryCode="NA";foreign.educationSystem="na-nied-primary-2024-v1";foreign.grade=7;String f=Diagnosis.scopeKey(foreign);foreign.foundationAscending=true;assertEquals(f,Diagnosis.scopeKey(foreign));assertTrue(KoreanFoundationUnits.available(foreign).isEmpty());for(Class<?> model:List.of(Learning.Profile.class,Learning.CurriculumSelection.class,Diagnosis.Plan.class,Learning.Session.class))assertEquals(1L,ObjectStreamClass.lookup(model).getSerialVersionUID());
 }
 @Test public void PureCountsPersistentStudyAndCountrySelectionSurviveSnapshots(){
  Learning.State s=student(true);s.profile.lastLearnedSkill=unit(s.profile,1,1,3).endpointSkill();Learning.beginDiagnostic(s,new Random(373));Diagnosis.Plan p=Diagnosis.currentPlan(s);int count=Diagnosis.remainingChecks(p);List<String> pending=new ArrayList<>(p.pending);Set<String> untested=new LinkedHashSet<>(p.untested);assertEquals(count,Diagnosis.remainingChecks(p));assertEquals(pending,p.pending);assertEquals(untested,p.untested);Diagnosis.UnitScreen screen=Diagnosis.screens(p).iterator().next();screen.status=Diagnosis.UnitStatus.RECENTLY_CHECKED;screen.reasons.put(screen.representatives.get(0),"unable");assertTrue(Diagnosis.studyUnits(s).contains(screen));Learning.State snapshot=LearningSnapshot.capture(s);assertEquals(Diagnosis.UnitStatus.RECENTLY_CHECKED,Diagnosis.screens(Diagnosis.currentPlan(snapshot)).iterator().next().status);String endpoint=s.profile.lastLearnedSkill,key=Diagnosis.scopeKey(s.profile);GlobalCurriculum.chooseCountry(s.profile,"NA");assertFalse(s.profile.foundationAscending);GlobalCurriculum.chooseCountry(s.profile,"KR");assertTrue(s.profile.foundationAscending);assertEquals(endpoint,s.profile.lastLearnedSkill);assertEquals(key,Diagnosis.scopeKey(s.profile));assertEquals(6,s.profile.grade);
 }
 @Test public void FoundationPracticeUsesAnExplicitEasierQueueAndNeverClearsAfterOneOrHelpedCorrect(){
  Learning.State s=student(true);s.profile.lastLearnedSkill=unit(s.profile,1,1,3).endpointSkill();Random r=new Random(374);Learning.beginDiagnostic(s,r);Diagnosis.Plan p=Diagnosis.currentPlan(s);Diagnosis.UnitScreen screen=p.unitScreens.values().stream().filter(x->x.representatives.contains("add9")).findFirst().orElseThrow();KoreanFoundationStudy.flagged(s,screen,"add9","unable",DAY);Learning.Session practice=Diagnosis.beginStudy(s,screen,r);assertEquals("foundationStudy",practice.mode);assertEquals(p.key,practice.foundationPlanKey);assertEquals(screen.key,practice.foundationUnitKey);String warm=practice.queue.get(0);assertTrue(Catalog.foundationOrder("add9").contains(warm));assertNotEquals("add9",warm);Question q=Learning.ensureQuestion(s,new Generator(r),DAY);assertEquals(warm,q.skillId);Learning.finishQuestion(s,false,DAY,r);assertEquals(Diagnosis.UnitStatus.NEEDS_STUDY,screen.status);q=Learning.ensureQuestion(s,new Generator(r),DAY);assertEquals(warm,q.skillId);Review.helpUsed(s,DAY);Learning.finishQuestion(s,false,DAY,r);assertEquals(Diagnosis.UnitStatus.NEEDS_STUDY,screen.status);assertTrue(Diagnosis.studyUnits(s).contains(screen));assertEquals(Review.GAP,2);assertEquals(Review.RECOVERY_CHECKS,2);
 }
}
